// Reads the request VeskaFlow sent, and prepares the text that was signed.
const item = $input.first();
let raw;
if (item.binary && item.binary.data) {
  // The Webhook node's "Raw Body" option keeps the exact bytes VeskaFlow signed.
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  raw = buf.toString('utf8');
} else {
  raw = JSON.stringify(item.json.body);
}
const headers = item.json.headers || {};
const timestamp = headers['x-veskaflow-timestamp'] || '';
const ageSeconds = Math.abs(Date.now() / 1000 - Number(timestamp));
return [{
  json: {
    signedString: timestamp + '.' + raw,
    signature: headers['x-veskaflow-signature'] || '',
    fresh: ageSeconds < 300,
    event: headers['x-veskaflow-event'] || '',
    delivery: headers['x-veskaflow-delivery'] || '',
    payload: JSON.parse(raw),
  },
}];

// Turns a platform event (for the VeskaFlow platform owner) into a short message.
const p = $('Check input').first().json.payload;
const e = p.event;
const d = p.data || {};
const shop = d.shop ? d.shop.name : '';
const pay = d.payment || {};
const owner = d.owner || {};
const lines = {
  'payment.submitted': 'Payment waiting: ' + shop + '\n' + pay.kind + ' ' + pay.period + ', PHP ' + pay.amount + '\nGCash ref: ' + pay.reference + '\nConfirm it in /Platform/Payments',
  'payment.confirmed': 'Payment confirmed: ' + shop + '\n' + pay.kind + ' ' + pay.period + ', PHP ' + pay.amount + '\nReceipt: ' + pay.receiptNo,
  'shop.signed_up': 'New shop signed up: ' + (d.shop ? d.shop.name : '') + '\nOwner: ' + owner.name + ' (' + owner.email + ')' + (d.needsApproval ? '\nWaiting for your approval' : ''),
  'test.ping': 'VeskaFlow test: the connection works.',
};
return [{ json: { text: lines[e] || ('VeskaFlow event: ' + e) } }];
